{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 instance does not have IMDSv2 enforced",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance lacks a metadata_options block, meaning Instance Metadata Service (IMDS) v1 is enabled by default. This allows SSRF attacks to retrieve temporary credentials without requiring a token."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 instance root volume encryption not explicitly configured",
      "resource": "aws_instance.web",
      "severity": "LOW",
      "explanation": "While AWS may encrypt volumes by default depending on account settings, explicit configuration of encrypted = true in the root_block_device ensures data at rest protection for the instance's primary storage."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added metadata_options with http_tokens set to 'required' to enforce IMDSv2 and prevent credential theft via SSRF. Added root_block_device with encrypted set to true to ensure the EBS volume is encrypted at rest."
}
